window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3f6a8b8ed518f86f"]={"versions": [{"id": "FIG-3f6a8b8ed518f86f", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm LinSM</code>) zur Spezifikation des Zustandsverhaltens des AUTOSAR Basic Software Moduls LIN State Manager (<code>LinSM</code>). Das Diagramm beschreibt die hierarchische Betriebsmodi- und Kommunikationszustandsverwaltung für LIN-Kanäle innerhalb des AUTOSAR Communication Stacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände</strong>:</li>\n<li><code>LINSM_UNINIT</code>: Initialer Zustand des Moduls vor der Initialisierung.</li>\n<li><code>LINSM_INIT</code>: Übergeordneter Superstate für initialisierte LIN-Kanäle.</li>\n<li><code>LINSM_NO_COM</code>: Unterzustand von <code>LINSM_INIT</code>, repräsentiert den Zustand ohne aktive LIN-Kommunikation.</li>\n<li><code>LINSM_FULL_COM</code>: Zusammengesetzter Unterzustand von <code>LINSM_INIT</code>, repräsentiert den Zustand mit aktiver Kommunikation.</li>\n<li><code>LINSM_RUN_SCHEDULE</code>: Unterzustand von <code>LINSM_FULL_COM</code>, aktiver Schedule-Ablauf auf dem LIN-Bus.</li>\n<li><code>LINSM_GOTO_SLEEP</code>: Unterzustand von <code>LINSM_FULL_COM</code>, Übergangszustand zum Versetzen des Busses in den Schlafmodus.</li>\n<li><strong>Schnittstellen und Trigger</strong>:</li>\n<li><code>LinSM_Init</code>: Initialisierungsfunktion zum Eintritt in <code>LINSM_INIT</code>.</li>\n<li><code>LinSM_RequesComMode(FULL_COM)</code>: API-Aufruf zur Anforderung des Vollkommunikationsmodus.</li>\n<li><code>LinSM_RequestComMode(NO_COM)</code>: API-Aufruf zur Anforderung des No-Communication-Modus.</li>\n<li><code>LinSM_GotoSleep_Confirmation</code>: Bestätigungs-Callback der unteren Schicht über den vollzogenen Sleep-Zustand.</li>\n<li><code>LINSM_SLEEP_SUPPORT==false</code>: Konfigurationsparameter/Bedingung, die das Schlafen des Busses umgeht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Modul startet im Zustand <code>LINSM_UNINIT</code>.</li>\n<li>Über den Aufruf <code>LinSM_Init</code> erfolgt der Übergang in den Superstate <code>LINSM_INIT</code>.</li>\n<li>Innerhalb von <code>LINSM_INIT</code> erfolgt kanalindividuell (<code>For each LIN channel</code>) über den Startzustand der Eintritt in <code>LINSM_NO_COM</code>.</li>\n<li>Der Funktionsaufruf <code>LinSM_RequesComMode(FULL_COM)</code> löst den Wechsel von <code>LINSM_NO_COM</code> in den Superstate <code>LINSM_FULL_COM</code> aus, wobei initial der Unterzustand <code>LINSM_RUN_SCHEDULE</code> eingenommen wird.</li>\n<li>Durch den Aufruf <code>LinSM_RequestComMode(NO_COM)</code> wechselt der Zustand von <code>LINSM_RUN_SCHEDULE</code> zu <code>LINSM_GOTO_SLEEP</code>.</li>\n<li>Aus <code>LINSM_GOTO_SLEEP</code> führt der Übergang zurück nach <code>LINSM_NO_COM</code>, sobald <code>LinSM_GotoSleep_Confirmation</code> eintrifft oder die Konfiguration <code>LINSM_SLEEP_SUPPORT==false</code> erfüllt ist.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Zustände und Übergangsbedingungen des LIN State Managers. Besondere Beachtung erfordert die Handhabung des Übergangs von <code>LINSM_GOTO_SLEEP</code> zu <code>LINSM_NO_COM</code>: Unterstützt der LIN-Cluster keinen Sleep-Modus (<code>LINSM_SLEEP_SUPPORT == false</code>), wird der Modus direkt gewechselt, andernfalls muss zwingend auf die asynchrone Bestätigung <code>LinSM_GotoSleep_Confirmation</code> gewartet werden. Implementierer müssen zudem beachten, dass der Initialzustand kanalindividuell instanziiert wird.</p>"}, {"id": "FIG-1485969bd1fe0f57", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm LinSM State Machine</code>) zur Spezifikation des Zustandsverhaltens des AUTOSAR Basic Software Moduls LIN State Manager (<code>LinSM</code>). Das Diagramm beschreibt die hierarchische Betriebsmodi- und Kommunikationszustandsverwaltung für LIN-Kanäle innerhalb des AUTOSAR Communication Stacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände</strong>:</li>\n<li><code>LINSM_UNINIT</code>: Initialer Zustand des Moduls vor der Initialisierung.</li>\n<li><code>LINSM_INIT</code>: Übergeordneter Superstate für initialisierte LIN-Kanäle.</li>\n<li><code>LINSM_NO_COM</code>: Unterzustand von <code>LINSM_INIT</code>, repräsentiert den Zustand ohne aktive LIN-Kommunikation.</li>\n<li><code>LINSM_FULL_COM</code>: Zusammengesetzter Unterzustand von <code>LINSM_INIT</code>, repräsentiert den Zustand mit aktiver Kommunikation.</li>\n<li><code>LINSM_RUN_SCHEDULE</code>: Unterzustand von <code>LINSM_FULL_COM</code>, aktiver Schedule-Ablauf auf dem LIN-Bus.</li>\n<li><code>LINSM_GOTO_SLEEP</code>: Unterzustand von <code>LINSM_FULL_COM</code>, Übergangszustand zum Versetzen des Busses in den Schlafmodus.</li>\n<li><strong>Schnittstellen, Guards und Trigger</strong>:</li>\n<li><code>LinSM_Init</code>: Initialisierungsfunktion zum Eintritt in <code>LINSM_INIT</code>.</li>\n<li><code>[reqComMode==FULL_COM]</code>: Guard-Bedingung für den Wechsel in den Vollkommunikationsmodus.</li>\n<li><code>[reqComMode==NO_COM]</code>: Guard-Bedingung für den Wechsel in den Schlaf-/Ruhezustand.</li>\n<li><code>LinSM_GotoSleep_Confirmation</code>: Bestätigungs-Callback der unteren Schicht über den vollzogenen Sleep-Zustand.</li>\n<li><code>LINSM_SLEEP_SUPPORT==false</code>: Konfigurationsparameter/Bedingung bei deaktivierter Sleep-Unterstützung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das Modul startet im Zustand <code>LINSM_UNINIT</code>.</li>\n<li>Über den Aufruf <code>LinSM_Init</code> erfolgt der Übergang in den Superstate <code>LINSM_INIT</code>.</li>\n<li>Innerhalb von <code>LINSM_INIT</code> erfolgt kanalindividuell (<code>For each LIN channel</code>) über den Startzustand der Eintritt in <code>LINSM_NO_COM</code>.</li>\n<li>Ist die Bedingung <code>[reqComMode==FULL_COM]</code> erfüllt, erfolgt der Wechsel von <code>LINSM_NO_COM</code> in den Superstate <code>LINSM_FULL_COM</code>, wobei initial der Unterzustand <code>LINSM_RUN_SCHEDULE</code> eingenommen wird.</li>\n<li>Bei erfüllter Bedingung <code>[reqComMode==NO_COM]</code> wechselt der Zustand von <code>LINSM_RUN_SCHEDULE</code> zu <code>LINSM_GOTO_SLEEP</code>.</li>\n<li>Aus <code>LINSM_GOTO_SLEEP</code> führt der Übergang zurück nach <code>LINSM_NO_COM</code>, sobald <code>LinSM_GotoSleep_Confirmation</code> eintrifft oder die Konfiguration <code>LINSM_SLEEP_SUPPORT==false</code> erfüllt ist.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Zustände und Übergangsbedingungen des LIN State Managers. Besondere Beachtung erfordert die Handhabung des Übergangs von <code>LINSM_GOTO_SLEEP</code> zu <code>LINSM_NO_COM</code>: Unterstützt der LIN-Cluster keinen Sleep-Modus (<code>LINSM_SLEEP_SUPPORT == false</code>), wird der Modus direkt gewechselt, andernfalls muss zwingend auf die asynchrone Bestätigung <code>LinSM_GotoSleep_Confirmation</code> gewartet werden. Implementierer müssen zudem beachten, dass der Initialzustand kanalindividuell instanziiert wird.</p>"}], "trans": [{"from": "FIG-3f6a8b8ed518f86f", "to": "FIG-1485969bd1fe0f57", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kopfzeile: Diagrammart und Name von <code>sm LinSM</code> zu <code>stm LinSM State Machine</code> geändert.</li>\n<li>Transition <code>LINSM_NO_COM</code> -> <code>LINSM_FULL_COM</code>: Auslöser/Bedingung von Funktionsaufruf <code>LinSM_RequesComMode(FULL_COM)</code> auf Guard-Condition <code>[reqComMode==FULL_COM]</code> umgestellt (Tippfehler im Funktionsnamen behoben).</li>\n<li>Transition <code>LINSM_RUN_SCHEDULE</code> -> <code>LINSM_GOTO_SLEEP</code>: Auslöser/Bedingung von Funktionsaufruf <code>LinSM_RequestComMode(NO_COM)</code> auf Guard-Condition <code>[reqComMode==NO_COM]</code> umgestellt.</li>\n</ul>"}]};
